Source code in <code>fastapi_basekit/aio/controller/base.py</code> <pre><code>def format_response(
    self,
    data: Any,
    pagination: Optional[Dict[str, Any]] = None,
    message: Optional[str] = None,
    response_status: str = "success",
) -&gt; BaseModel:
    schema = self.get_schema_class()

    # Robust Pydantic v2 validation. Each branch falls back to the
    # raw value when the schema doesn't fit (custom-action endpoints
    # often return ad-hoc dicts that don't match the controller's
    # default schema_class — those should pass through untouched).
    #
    # Cuando un endpoint custom ya devuelve un modelo Pydantic específico
    # (distinto a ``schema``), no lo re-casteeamos al schema por defecto:
    # eso rompe el ``response_model`` declarado en la ruta y provoca
    # ResponseValidationError. Se convierte a dict limpio y FastAPI se
    # encarga de validar/serializar contra el response_model del endpoint.
    if isinstance(data, BaseModel):
        if isinstance(data, schema):
            data_parsed = data
        else:
            data_parsed = self.to_dict(data)

    elif isinstance(data, list):
        # Si la lista contiene modelos Pydantic distintos al schema por
        # defecto, respetarlos; de lo contrario validar normalmente.
        if data and all(
            isinstance(item, BaseModel) and not isinstance(item, schema)
            for item in data
        ):
            data_parsed = [self.to_dict(item) for item in data]
        else:
            data_dicts = [self.to_dict(item) for item in data]
            try:
                adapter = TypeAdapter(List[schema])
                data_parsed = adapter.validate_python(data_dicts)
            except Exception:
                data_parsed = data_dicts

    elif isinstance(data, dict):
        try:
            data_parsed = schema.model_validate(data)
        except Exception:
            data_parsed = data

    elif hasattr(data, "__dict__"):
        data_dict = self.to_dict(data)
        try:
            data_parsed = schema.model_validate(data_dict)
        except Exception:
            data_parsed = data_dict

    elif data is None:
        data_parsed = None
    else:
        data_parsed = data

    response_cls = BasePaginationResponse if pagination else BaseResponse

    # Construcción dinámica de argumentos
    kwargs = {
        "data": data_parsed,
        "message": message or "Operación exitosa",
        "status": response_status,
    }
    if pagination:
        kwargs["pagination"] = pagination

    return response_cls(**kwargs)
</code></pre>

Source code in <code>fastapi_basekit/aio/sqlalchemy/service/base.py</code> <pre><code>async def create(
    self,
    payload: BaseModel | Dict[str, Any],
    check_fields: Optional[List[str]] = None,
) -&gt; ModelT:
    data = (
        payload.model_dump() if isinstance(payload, BaseModel) else payload
    )
    fields = (
        check_fields
        if check_fields is not None
        else self.duplicate_check_fields
    )
    if fields:
        filters = {f: data[f] for f in fields if f in data}
        if filters:
            existing = await self.repository.get_by_filters(filters)
            if existing:
                raise DatabaseIntegrityException(
                    message="Registro ya existe", data=filters
                )
    created = await self.repository.create(data)
    return created
